Namespace: mne · Library: MNE Library · Source: mne/mne_process_description.h #include <mne/mne_process_description.h> struct mne::CovDefinition Covariance matrix computation definition. Ported from covDefRec (MNE-C browser_types.h). src/examples/ex_mne_api/main.cpp // An MNE-C covariance description (mne_process_raw --cov): pre-stimulus data of events 1 and 2 const QString covDescPath = tmp.filePath("audvis.cov"); QFile covDescFile(covDescPath); ok &= covDescFile.open(QIODevice::WriteOnly | QIODevice::Text); covDescFile.write("cov {
" " eegReject 14.230782369752743e-9
" " def {
" " event 1
" " event 2
" " tmin -0.2
" " tmax 0.0
" " }
" "}
"); covDescFile.close(); std::optional<CovDescription> covariance = MNEDescriptionParser::read_covariance(covDescPath.toStdU16String()); covariance->rej.megGradReject = covariance->rej.megMagReject = covariance->rej.eogReject = 0.0f; // EEG limit only const CovDefinition& preStim = covariance->defs.front(); const FiffCov noiseCov = FiffCov::compute_from_epochs(raw, events.events, {1, 2}, preStim.tmin, preStim.tmax, preStim.bmin, preStim.bmax, preStim.doBaseline, covariance->removeSampleMean, preStim.ignore, preStim.delay, &covariance->rej);

